let embeddedRule0229: RuleEntry = RuleEntry(
    id: "phb_ch07_spell_index",
    book: "PHB",
    chapterNumber: 7,
    chapterTitle: "Magic",
    breadcrumbs: "Player's Handbook > Chapter 7: Magic > Spell Index",
    topic: "Spell Index",
