let embeddedRule0233: RuleEntry = RuleEntry(
    id: "phb_ch09_attacking_with_two_weapons",
    book: "PHB",
    chapterNumber: 9,
    chapterTitle: "Combat",
    breadcrumbs: "Player's Handbook > Chapter 9: Combat > Attacking with Two Weapons",
    topic: "Attacking with Two Weapons",
    ruleType: "core_rule",
    summary: "A tricky fighting style available only to warriors and rogues is that of fighting with two weapons simultaneously. The character chooses not to use a shield in favor of another weapon, granting him a greater number of attacks, with a pen...",
    content: "A tricky fighting style available only to warriors and rogues is that of fighting with two weapons simultaneously. The character chooses not to use a shield in favor of another weapon, granting him a greater number of attacks, with a penalty to his attack rolls (rangers are exempt from the attack roll penalty).\n\nWhen using a second weapon in his off-hand, a character is limited in his weapon choice. His principal weapon can be whatever he chooses, provided it can be wielded with one hand. The second weapon must be smaller in size and weight than the character's main weapon (though a dagger can always be used as a second weapon, even if the primary weapon is also a dagger). A fighter can use a long sword and a short sword, or a long sword and a dagger, but he cannot use two long swords. Nor can the character use a shield, unless it is kept strapped onto his back.\n\nWhen attacking, all characters but rangers suffer penalties to their attack rolls. Attacks made with the main weapon suffer a -2 penalty, and attacks made with the second weapon suffer a -4 penalty. The character's Reaction Adjustment (based on his Dexterity, see Table 2) modifies this penalty. A low Dexterity score will worsen the character's chance to hit with each attack. A high Dexterity can negate this particular penalty, although it cannot result in a positive modifier on the attack rolls for either weapon (i.e., the Reaction Adjustment can, at best, raise the attack roll penalties to 0).\n\nThe use of two weapons enables the character to make one additional attack each combat round, with the second weapon. The character gains only one additional attack each round, regardless of the number of attacks he may normally be allowed. Thus, a warrior able to attack 3/2 (once in the first round and twice in the second) can attack 5/2 (twice in the first round and three times in the second).",
    tables: [],
    relatedRuleIds: [],
    relatedSpells: [],
    relatedMagicItems: [],
    searchKeywords: ["attacking", "attacking with two weapons", "dexterity", "weapons", "with"]
)

let embeddedRule0234: RuleEntry = RuleEntry(
    id: "phb_ch09_calculating_thac0",
    book: "PHB",
    chapterNumber: 9,
    chapterTitle: "Combat",
    breadcrumbs: "Player's Handbook > Chapter 9: Combat > Calculating THAC0",
    topic: "Calculating THAC0",
    ruleType: "core_rule",
    summary: "To make an attack roll, the character's THAC0 must be known. This depends on the group and level, if the attacker is a player character or NPC, or the Hit Dice if the attacker is a monster or an animal.",
    content: "To make an attack roll, the character's THAC0 must be known. This depends on the group and level, if the attacker is a player character or NPC, or the Hit Dice if the attacker is a monster or an animal. All 1st-level characters have THAC0s of 20, regardless of class.\n\nFor a character of level 1 through level 20, consult Table 53. This table lists the THAC0 number of each group through 20th level, so players don't have to perform any calculations.\n\nFor a character higher than 20th level, find the Improvement Rate for the character's group in Table 54. There you'll find the number of levels a character must advance to reduce his THAC0 by 1 (or more) points. Calculate the character's THAC0 according to his level.\n\nThe (DMG) contains the information on monster THAC0s.\n\n[TABLE_REF: Table 53: Calculated THAC0s]\n\n[TABLE_REF: Table 54: THAC0 Advancement]",
